class CanvasBase(QWidget):
    """Shared canvas scaffolding: scaling, HUD, overlays, particles, trail."""

    def __init__(self):
        super().__init__()
        self.fr = None
        self.trail = []
        self.particles = []
        self._episode = None
        self._was_dead = False
        rng = random.Random(7)
        self.stars = [(rng.uniform(0, 480), rng.uniform(0, 320),
                       rng.uniform(1.0, 2.4), rng.randint(40, 170))
                      for _ in range(90)]
        self.setMinimumSize(480, 320)

    def burst(self, cx, cy, colors=None, n=18):
        colors = colors or ("#00e5ff", "#8ef9ff", "#ffffff", "#ffd54f")
        self.particles = [(cx + math.cos(a := random.uniform(0, 2 * math.pi))
                           * random.uniform(8, 52),
                           cy + math.sin(a) * random.uniform(8, 52),
                           random.uniform(2.5, 6.5), random.choice(colors))
                          for _ in range(n)]

    def _begin(self, fr):
        if fr.get("episode") != self._episode:
            self._episode = fr.get("episode")
            self.trail.clear()
            self.particles.clear()
            self._was_dead = False

    def _end(self, fr):
        self._was_dead = bool(fr.get("dead"))
        self.fr = fr
        self.update()

    def set_frame(self, fr):
        raise NotImplementedError

    def _draw(self, p, W, H):
        raise NotImplementedError

    def paintEvent(self, _):
        p = QPainter(self)
        p.setRenderHint(QPainter.Antialiasing)
        W, H = 480, 320
        s = min(self.width() / W, self.height() / H)
        p.translate((self.width() - W * s) / 2, (self.height() - H * s) / 2)
        p.scale(s, s)
        p.setClipRect(QRectF(0, 0, W, H))
        if self.fr is None:
            self._placeholder(p, W, H)
        else:
            self._draw(p, W, H)

    def draw_particles(self, p):
        for x, y, s, col in self.particles:
            p.setPen(Qt.NoPen)
            p.setBrush(QColor(col))
            p.drawRect(QRectF(x - s / 2, y - s / 2, s, s))

    def hud(self, p, W, score, episode, right_text=None):
        p.setFont(QFont("Arial", 21, QFont.Bold))
        p.setPen(QColor(0, 0, 0, 120))
        p.drawText(QRectF(1, 9, W, 32), Qt.AlignHCenter | Qt.AlignTop, str(score))
        p.setPen(QColor("white"))
        p.drawText(QRectF(0, 8, W, 32), Qt.AlignHCenter | Qt.AlignTop, str(score))
        p.setFont(QFont("Arial", 10, QFont.Bold))
        p.setPen(QColor(0, 0, 0, 120))
        p.drawText(QPointF(11, 17), f"Attempt {episode}")
        p.setPen(QColor("white"))
        p.drawText(QPointF(10, 16), f"Attempt {episode}")
        if right_text:
            p.setPen(QColor(0, 0, 0, 120))
            p.drawText(QRectF(W - 129, 9, 120, 20), Qt.AlignRight, right_text)
            p.setPen(QColor("white"))
            p.drawText(QRectF(W - 130, 8, 120, 20), Qt.AlignRight, right_text)

    def crash_overlay(self, p, W, H):
        p.fillRect(QRectF(0, 0, W, H), QColor(200, 30, 30, 55))
        p.setFont(QFont("Arial", 24, QFont.Bold))
        p.setPen(QColor(0, 0, 0, 130))
        p.drawText(QRectF(1, H / 2 - 69, W, 40), Qt.AlignCenter, "CRASHED!")
        p.setPen(QColor("white"))
        p.drawText(QRectF(0, H / 2 - 70, W, 40), Qt.AlignCenter, "CRASHED!")

    def _placeholder(self, p, W, H):
        grad = QLinearGradient(0, 0, 0, H)
        grad.setColorAt(0.0, QColor("#0d0f1c"))
        grad.setColorAt(1.0, QColor("#181b33"))
        p.fillRect(QRectF(0, 0, W, H), QBrush(grad))
        p.setPen(Qt.NoPen)
        for x, y, s, a in self.stars:
            p.setBrush(QColor(255, 255, 255, a))
            p.drawRect(QRectF(x, y, s, s))
        p.setFont(QFont("Arial", 14, QFont.Bold))
        p.setPen(QColor(0, 0, 0, 120))
        p.drawText(QRectF(1, H / 2 - 35, W, 30), Qt.AlignCenter, GAME_TITLE)
        p.setPen(QColor("white"))
        p.drawText(QRectF(0, H / 2 - 36, W, 30), Qt.AlignCenter, GAME_TITLE)
        p.setFont(QFont("Arial", 11))
        p.setPen(QColor("#9fb3c8"))
        p.drawText(QRectF(0, H / 2, W, 26), Qt.AlignCenter, "Press ▶ Start training")
